<?php
declare(strict_types=1);require_once __DIR__.'/config/sales_step15.php';$error=null;$rows=[];$customers=[];$m=['sales'=>0,'customers'=>0,'linked'=>0,'invoices'=>0,'delivered'=>0,'returns'=>0.0,'refunds'=>0.0,'receivable'=>0.0,'credit_due'=>0.0,'effective'=>0.0,'net_collected'=>0.0,'followups'=>0];
try{$pdo=business_db();sales_step15_ensure($pdo);sales_step15_backfill($pdo);$ctx=sales_step15_context($pdo);$orgId=(int)$ctx['organization_id'];$rows=sales_step15_sales_rows($pdo,$orgId);foreach($rows as $r){if($r['sale_status']!=='active')continue;$m['sales']++;if($r['customer_id'])$m['linked']++;if($r['invoice_id'])$m['invoices']++;if($r['delivery_status']==='delivered')$m['delivered']++;$m['returns']+=(float)$r['return_credit'];$m['refunds']+=(float)$r['refund_amount'];$m['receivable']+=(float)$r['receivable_amount'];$m['credit_due']+=(float)$r['customer_credit_due'];$m['effective']+=(float)$r['effective_charge'];$m['net_collected']+=(float)$r['net_collected'];}$m['customers']=(int)$pdo->query("SELECT COUNT(*) FROM crm_customers WHERE organization_id=".(int)$orgId." AND status='active'")->fetchColumn();$stmt=$pdo->prepare("SELECT COUNT(*) FROM crm_interactions WHERE organization_id=? AND status='open'");$stmt->execute([$orgId]);$m['followups']=(int)$stmt->fetchColumn();$stmt=$pdo->prepare("SELECT c.id,c.customer_name,c.customer_code,COUNT(f.id) sales_count,COALESCE(SUM(f.effective_charge),0) effective_charge,COALESCE(SUM(f.net_collected),0) collected,COALESCE(SUM(f.receivable_amount),0) receivable FROM crm_customers c LEFT JOIN sales_fulfillment_ledger f ON f.organization_id=c.organization_id AND f.customer_id=c.id WHERE c.organization_id=? GROUP BY c.id ORDER BY effective_charge DESC,c.customer_name LIMIT 20");$stmt->execute([$orgId]);$customers=$stmt->fetchAll();}catch(Throwable $e){$error=$e->getMessage();}
function sa15_h(mixed $v):string{return htmlspecialchars((string)$v,ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8');}function sa15_m(mixed $v):string{return '₹'.number_format((float)$v,2,'.',',');}
?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex,nofollow"><title>STEP 15 Analytics - Healthcare Wellness Club</title><link rel="stylesheet" href="assets/dashboard.css"><link rel="stylesheet" href="assets/step10.css"><link rel="stylesheet" href="assets/product_pro.css"></head><body><header class="os-topbar"><div class="os-topbar-inner"><a class="os-brand" href="sales_fulfillment.php"><img src="../img/logo.png" alt="logo"><span><strong>Healthcare Wellness Club</strong><small>STEP 15 • Customer & Fulfillment Analytics</small></span></a><div class="os-top-actions"><a class="os-btn" href="sales_receivables.php">Receivables</a><a class="os-btn" href="sales_export_step15.php">Export</a><a class="os-btn primary" href="sales_fulfillment.php">Fulfillment</a></div></div></header><div class="os-layout"><aside class="os-sidebar"><div class="os-nav-label">Analytics</div><nav class="os-nav"><a href="customer_center.php"><i class="dot"></i>Customers</a><a href="sales_fulfillment.php"><i class="dot"></i>Fulfillment</a><a href="sales_receivables.php"><i class="dot"></i>Receivables</a><a href="crm_followups.php"><i class="dot"></i>Follow-ups</a><a class="active" href="sales_analytics_step15.php"><i class="dot"></i>Analytics</a><a href="step15_audit.php"><i class="dot"></i>Audit</a></nav></aside><main class="os-main"><section class="os-hero s10-hero"><div class="os-kicker">STEP 15I • CUSTOMER / FULFILLMENT ANALYTICS</div><h1>Measure customer activity, fulfillment health and after-sales exposure separately.</h1><p>Effective charge accounts for posted return credits; net collected accounts for active refunds. Original sale evidence remains unchanged.</p><div class="os-status-row"><span class="os-chip <?= $error===null?'good':'' ?>"><?= $error===null?'STEP 15 ANALYTICS LIVE':'Review required' ?></span><span class="os-chip"><?= $m['sales'] ?> active sales</span><span class="os-chip"><?= $m['customers'] ?> active customers</span></div></section><?php if($error):?><div class="pp-alert bad"><strong>Analytics diagnostic:</strong> <?= sa15_h($error) ?></div><?php endif;?><section class="s10-kpis"><div class="s10-kpi"><small>Effective Sales</small><strong><?= sa15_m($m['effective']) ?></strong><span><?= $m['sales'] ?> active sales • <?= $m['linked'] ?> customer-linked</span></div><div class="s10-kpi"><small>Net Collected</small><strong><?= sa15_m($m['net_collected']) ?></strong><span><?= sa15_m($m['refunds']) ?> refunds</span></div><div class="s10-kpi"><small>Receivable</small><strong><?= sa15_m($m['receivable']) ?></strong><span><?= sa15_m($m['credit_due']) ?> customer credit due</span></div><div class="s10-kpi"><small>Fulfillment</small><strong><?= $m['delivered'] ?> / <?= $m['sales'] ?></strong><span><?= $m['invoices'] ?> invoices • <?= $m['followups'] ?> open follow-ups</span></div></section><?php if(!$error):?><section class="pp-grid" style="margin-top:14px"><article class="os-card pp-span-7"><h2>Customer Value & Balance</h2><div class="pp-table-wrap"><table class="pp-table"><thead><tr><th>Customer</th><th>Sales</th><th>Effective Charge</th><th>Net Collected</th><th>Receivable</th></tr></thead><tbody><?php foreach($customers as $c):?><tr><td><a href="customer_detail.php?id=<?= (int)$c['id'] ?>"><b><?= sa15_h($c['customer_name']) ?></b></a><small><?= sa15_h($c['customer_code']) ?></small></td><td><?= (int)$c['sales_count'] ?></td><td><?= sa15_m($c['effective_charge']) ?></td><td><?= sa15_m($c['collected']) ?></td><td><b><?= sa15_m($c['receivable']) ?></b></td></tr><?php endforeach;?><?php if(!$customers):?><tr><td colspan="5">No Customer Master activity yet.</td></tr><?php endif;?></tbody></table></div></article><article class="os-card pp-span-5"><h2>After-Sales Health</h2><div class="pp-source"><b>Return Credits</b><span><?= sa15_m($m['returns']) ?></span></div><div class="pp-source"><b>Refunds</b><span><?= sa15_m($m['refunds']) ?></span></div><div class="pp-source"><b>Customer Credit Due</b><span><?= sa15_m($m['credit_due']) ?></span></div><div class="pp-source"><b>Delivered Sales</b><span><?= $m['delivered'] ?> / <?= $m['sales'] ?></span></div><div class="pp-source"><b>Open CRM Follow-ups</b><span><?= $m['followups'] ?></span></div></article></section><?php endif;?><div class="os-footer-note"><strong>Analytics rule:</strong> returns reduce effective customer charge; refunds reduce net collected cash; neither overwrites the original invoice.</div></main></div><script src="assets/business-collapsible.js?v=20260820-1" defer></script></body></html>
